const number=value=>new Intl.NumberFormat('de-DE').format(Number(value)||0);
function date(value){if(!value)return '—';const raw=String(value),d=new Date(raw.includes('T')?raw:raw.replace(' ','T')+'Z');return Number.isNaN(d.getTime())?raw:d.toLocaleString('sq-AL',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});}
const badge=value=>`<span class="badge ${Object.hasOwn(statusLabels,value)?value:''}"><i class="status-dot"></i>${esc(statusLabels[value]||value)}</span>`;
const button=(label,action,kind='',symbol='')=>`<button type="button" class="button ${kind}" data-action="${esc(action)}">${symbol?icon(symbol):''}${esc(label)}</button>`;
