const accountLink=u=>`<a class="account-cell" href="#/account/${u.id}/profile"><span class="account-initial">${esc(u.username.slice(0,2).toUpperCase())}</span><span><strong>${esc(u.username)}</strong><span class="subline">#${u.id}</span></span></a>`;
const empty=(title='Nuk ka të dhëna',detail='Regjistrimet do të shfaqen këtu sapo të jenë të disponueshme.')=>`<div class="empty-state">${icon('grid')}<strong>${esc(title)}</strong>${esc(detail)}</div>`;
function table(rows,columns){return rows.length?`<div class="table-wrap"><table><thead><tr>${columns.map(([label])=>`<th scope="col">${esc(label)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${columns.map(([,render])=>`<td>${render(row)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty();}
function panel(title,subtitle,body,action=''){return `<section class="panel"><div class="panel-heading"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${action}</div>${body}</section>`;}
const metric=(label,value,note,symbol,highlight=false)=>`<article class="metric${highlight?' highlight':''}">${highlight?'<span class="accent-line"></span>':''}<div class="metric-label">${esc(label)}<span class="metric-icon">${icon(symbol)}</span></div><div class="metric-value">${esc(value)}</div><p class="metric-note">${esc(note)}</p></article>`;
