$('mobileToggle').onclick=()=>{const open=$('sidebar').classList.toggle('open');$('mobileShade').classList.toggle('visible',open);$('mobileToggle').setAttribute('aria-expanded',String(open));};$('mobileShade').onclick=closeMobile;
$('dialogClose').onclick=()=>$('dialog').close();
document.addEventListener('click',e=>{if(e.target.closest('[data-close-dialog]'))$('dialog').close();if(e.target.closest('[data-action="refresh"]'))renderRoute();});
$('search').onsubmit=e=>{e.preventDefault();const q=new FormData(e.currentTarget).get('q').trim();if(q)location.hash='/search?q='+encodeURIComponent(q);};
$('logout').innerHTML=icon('logout');$('logout').onclick=async()=>{try{await api('/api/auth/logout','POST',{});}catch{}finally{sessionStorage.removeItem('sportsbook_token');location.replace('/');}};
