(async()=>{try{const d=await api('/api/access/me');me=d.user;permissions=new Set(d.permissions);if(me.role==='user'){location.replace('/');return;}document.title='EURO97 · '+labels[me.role];$('identity').textContent=me.username;$('roleLabel').textContent=labels[me.role]+(me.role==='center'?' · Superadmin':'');$('avatar').textContent=$('topAvatar').textContent=me.username.slice(0,2).toUpperCase();$('workspaceLabel').textContent=me.role==='center'?'Qendra e administrimit':'Rrjeti · '+labels[me.role];document.body.style.visibility='visible';navigation();$('connection').classList.add('online');$('connection').querySelector('span').textContent='Platforma aktive';await renderRoute();}catch(error){sessionStorage.removeItem('sportsbook_token');location.replace('/');heading('Hyr në llogarinë tënde','Përdor llogarinë e stafit për të hyrë në panel.','EURO97');$('content').innerHTML=empty('Kërkohet identifikimi',error.message)+'<div style="text-align:center"><a class="button primary" href="/">Shko te login</a></div>';}})();


async function acceptancePage(ctx){
 const data=await ctx.get('/api/center/ticket-acceptance');if(!ctx.valid())return;
 const fields=[['maxStake','Shuma maksimale (EUR)','0.01',100000000],['maxPayout','Fitimi i mundshëm maksimal (EUR)','0.01',100000000],['maxOdds','Koeficienti total maksimal','0.01',1000000],['maxSelections','Numri maksimal i zgjedhjeve','1',100]];
 const cards=['live','prematch'].map(kind=>panel(kind==='live'?'Biletat Live':'Biletat Prematch','Pranim automatik vetëm brenda të gjithë kufijve.',
 '<div class="panel-body"><label class="acceptance-toggle"><input type="checkbox" name="'+kind+'.enabled" '+(data.rules[kind].enabled?'checked':'')+'> Aktivizo pranimin automatik</label><div class="form-grid">'+fields.map(([key,label,step,max])=>'<label>'+label+'<input type="number" placeholder="Pa limit shtesë" min="'+step+'" max="'+max+'" step="'+step+'" name="'+kind+'.'+key+'" value="'+(data.rules[kind][key]??'')+'"></label>').join('')+'</div></div>')).join('');
 ctx.commit('<div class="info-note">Fushat bosh = pa limit shtesë. Plotëso vetëm kufijtë që dëshiron; nëse të gjitha janë bosh, nuk ka kufij shtesë për pranimin automatik. Zbatohet vetëm për biletat e reja. Biletat jashtë kufijve mbeten në pritje për Qendrën. Për biletat e përziera duhet të aktivizohen të dy llojet dhe të plotësohen të dy grupet e kufijve. Fitimi i mundshëm përfshin edhe shumën e luajtur. Limitet e llogarisë, ligës dhe riskut vazhdojnë të zbatohen.</div><form id="acceptanceForm" class="form-stack">'+cards+'<div class="form-actions"><button class="button primary" type="submit">Ruaj konfigurimin</button></div></form>');
 let version=data.version;
 bindForm('acceptanceForm',async form=>{const rules={};for(const kind of ['live','prematch']){rules[kind]={enabled:form.has(kind+'.enabled')};for(const [key] of fields)rules[kind][key]=form.get(kind+'.'+key)===''?null:Number(form.get(kind+'.'+key));}const saved=await api('/api/center/ticket-acceptance','PUT',{rules,version});version=saved.version;notice('Konfigurimi u ruajt. Rregullat zbatohen për biletat e reja.');});
}
